from sklearn.compose import ColumnTransformer
from sklearn.impute import SimpleImputer
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import OneHotEncoder
from xgboost import XGBClassifier
from sklearn.base import BaseEstimator, TransformerMixin

class TargetEncoder(BaseEstimator, TransformerMixin):
    def __init__(self, target_col, cols):
        self.target_col = target_col
        self.cols = cols
        self.encodings = {}

    def fit(self, X, y):
        for col in self.cols:
            self.encodings[col] = X.groupby(col)[self.target_col].mean()
        return self

    def transform(self, X):
        X_encoded = X.copy()
        for col, encoding in self.encodings.items():
            X_encoded[f"{col}_target_enc"] = X[col].map(encoding)
        return X_encoded

def build_model(X_train, y_train):
    numeric = X_train.select_dtypes(include=["number"]).columns
    categorical = X_train.select_dtypes(exclude=["number"]).columns

    preprocessing = ColumnTransformer([
        ("numeric", SimpleImputer(strategy="median"), numeric),
        ("categorical", Pipeline([
            ("imputer", SimpleImputer(strategy="most_frequent")),
            ("encoder", OneHotEncoder(handle_unknown="ignore")),
        ]), categorical),
    ])

    target_encoder = TargetEncoder(target_col='credit_amount', cols=['checking_status', 'credit_history', 'purpose', 'personal_status', 'other_parties', 'property_magnitude', 'job', 'own_telephone', 'foreign_worker'])

    return Pipeline([
        ("preprocessing", preprocessing),
        ("target_encoder", target_encoder),
        ("classifier", XGBClassifier(use_label_encoder=False, eval_metric='logloss')),
    ])
